package com.coffeeshop.model;import java.math.BigDecimal;import java.time.LocalDate;import java.util.List;public final class ReportModels{private ReportModels(){}public record Summary(long completedOrders,BigDecimal grossSales,BigDecimal discounts,BigDecimal tax,BigDecimal netSales,BigDecimal expenses){}public record Daily(LocalDate date,long orders,BigDecimal sales){}public record Payment(String method,BigDecimal amount){}public record LowStock(String code,String name,BigDecimal stock,BigDecimal reorder,String unit){}public record Report(Summary summary,List<Daily>daily,List<Payment>payments,List<LowStock>lowStock){public Report{daily=List.copyOf(daily);payments=List.copyOf(payments);lowStock=List.copyOf(lowStock);}}}
